.gv{display:flex;flex-direction:column;gap:.6rem;max-width:100%;overflow:hidden;--gv-ink:#2a2d33;--gv-card:#f6f4ef;--gv-accent:#c2562b;--gv-line:#c9c3b6}
html[data-theme=dark] .gv{--gv-ink:#e6e2da;--gv-card:#1d2024;--gv-accent:#e9824f;--gv-line:#3b4048}
.gv-controls{display:flex;flex-direction:column;gap:.45rem;color:var(--gv-ink)}
.gv-range{display:flex;flex-wrap:wrap;align-items:center;gap:.5rem;font-size:.9rem}
.gv-range input{flex:1 1 100%;min-width:0}
.gv-row{display:flex;flex-wrap:wrap;gap:.4rem;align-items:center;font-size:.85rem}
.gv-row input{width:4.5em;padding:.2rem .3rem;border:1px solid var(--gv-line);border-radius:4px;background:transparent;color:var(--gv-ink)}
.gv button{padding:.3rem .7rem;border:1px solid var(--gv-line);border-radius:6px;background:var(--gv-card);color:var(--gv-ink);font:inherit;font-size:.85rem;cursor:pointer}
.gv button[aria-pressed=true],.gv #play{border-color:var(--gv-accent)}
.gv-stage{position:relative;background:var(--gv-card);border:1px solid var(--gv-line);border-radius:10px;padding:.3rem}
.gv-stage svg{display:block;width:100%;height:auto}
.gv-viewlabel{position:absolute;left:.6rem;top:.4rem;font-size:.72rem;color:var(--gv-ink);opacity:.75}
.gv-accent path{fill:url(#gv-ball)}
.gv-sweep path{stroke-dasharray:4 4;opacity:.6}
.gv-mark circle{fill:var(--gv-card);stroke:var(--gv-accent);stroke-width:1.2}
.gv-mark text{font-size:9px;font-weight:700;fill:var(--gv-ink)}
.gv-read{display:grid;grid-template-columns:repeat(auto-fit,minmax(8.5rem,1fr));gap:.3rem .8rem;font-size:.85rem;color:var(--gv-ink)}
.gv-read div{display:flex;justify-content:space-between;border-bottom:1px solid var(--gv-line);padding:.15rem 0}
.gv-status{margin:0;font-size:.82rem;color:var(--gv-ink)}
.gv-msg{margin:0;font-size:.82rem;color:var(--gv-accent);min-height:1.1em}
.gv-legend{margin:0;padding-left:1.3rem;font-size:.8rem;color:var(--gv-ink);columns:2 14rem}
.gv-details{font-size:.82rem;color:var(--gv-ink)}

