// Two-ball centrifugal (Watt-type) governor - pure model, millimetres, z up.
// DESIGN (topology): base plate -> foot bearing + bracket post -> upper bearing housing
// -> vertical spindle (rotates, phase phi) -> fixed head yoke at Z_TOP carries two arm
// hinges at radius E on a diametral plane. Arm i (side s=+1/-1) of fixed length L
// carries a ball. A link of fixed length B joins arm point at distance A from hinge to
// sleeve lug pin at radius C. Sleeve slides on spindle (rotates with it); lower stop
// collar and upper stop collar bound its travel, giving arm stops TH_MIN..TH_MAX.
// Idealizations: massless rigid arms and links, point-mass balls, massless frictionless
// sleeve (pure Watt), no load on the sleeve, ideal joints, constant imposed speed.
export const DIM = {
  L: 220, E: 24, A: 110, B: 110, C: 26, Z_TOP: 420, BALL_R: 38,
  SPINDLE_R: 9, SLEEVE_R: 19, SLEEVE_BELOW: 46, SLEEVE_ABOVE: 16,
  TH_MIN: 20 * Math.PI / 180, TH_MAX: 64 * Math.PI / 180,
  BASE_Z: 18, HOUSING_Z0: 128, HOUSING_Z1: 158, SPINDLE_TOP: 452, FOOT_Z1: 58,
  PULLEY_Z0: 70, PULLEY_Z1: 106, PULLEY_R: 52, POST: [0, -128], POST_R: 13,
  G: 9810, RPM_MAX: 140, DAMP: 2.2
};
const D = DIM;
export const omegaOf = rpm => rpm * Math.PI / 30;

// Equilibrium residual of the arm about its hinge: g tan(th) = w^2 (E + L sin th)
function residual(th, w) { return D.G * Math.tan(th) - w * w * (D.E + D.L * Math.sin(th)); }

export function freeEquilibrium(rpm) {
  const w = omegaOf(rpm);
  if (w <= 0) return 0;
  let lo = 1e-6, hi = Math.PI / 2 - 1e-6, prev = lo, n = 400;
  for (let i = 1; i <= n; i++) {
    const t = lo + (hi - lo) * i / n;
    if (residual(t, w) >= 0) { let a = prev, b = t;
      for (let j = 0; j < 60; j++) { const m = (a + b) / 2; if (residual(m, w) >= 0) b = m; else a = m; }
      return (a + b) / 2; }
    prev = t;
  }
  return hi;
}
export function equilibrium(rpm) {
  const free = freeEquilibrium(rpm);
  const th = Math.min(D.TH_MAX, Math.max(D.TH_MIN, free));
  const stop = free < D.TH_MIN ? 'lower' : free > D.TH_MAX ? 'upper' : 'none';
  return { theta: th, free, stop };
}
// speed at which arms just lift off the lower stop / reach the upper stop
export function speedAt(th) { return Math.sqrt(D.G * Math.tan(th) / (D.E + D.L * Math.sin(th))) * 30 / Math.PI; }

// Sleeve pin height from link closure
export function sleeveZ(th) {
  const ax = D.E + D.A * Math.sin(th), az = D.Z_TOP - D.A * Math.cos(th);
  const dx = ax - D.C;
  return az - Math.sqrt(D.B * D.B - dx * dx);
}
export const SLEEVE_MIN = sleeveZ(D.TH_MIN), SLEEVE_MAX = sleeveZ(D.TH_MAX);
export const STOP_LOW_TOP = SLEEVE_MIN - D.SLEEVE_BELOW;   // lower collar face
export const STOP_HIGH_BOT = SLEEVE_MAX + D.SLEEVE_ABOVE;  // upper collar face

// World pose of everything that moves
export function pose(state) {
  const th = state.theta, phi = state.phi;
  const u = [Math.cos(phi), Math.sin(phi), 0], n = [-Math.sin(phi), Math.cos(phi), 0];
  const zs = sleeveZ(th);
  const sides = [1, -1].map(s => {
    const P = [s * D.E * u[0], s * D.E * u[1], D.Z_TOP];
    const at = d => [P[0] + s * d * Math.sin(th) * u[0], P[1] + s * d * Math.sin(th) * u[1], D.Z_TOP - d * Math.cos(th)];
    return { s, hinge: P, joint: at(D.A), ball: at(D.L), armTip: at(D.L - D.BALL_R * 0.4),
      pin: [s * D.C * u[0], s * D.C * u[1], zs], dir: [s * u[0], s * u[1], 0] };
  });
  return { theta: th, phi, u, n, zs, sleeve: [zs - D.SLEEVE_BELOW, zs + D.SLEEVE_ABOVE], sides,
    ballRadius: D.E + D.L * Math.sin(th), lift: zs - SLEEVE_MIN };
}

export function initial() {
  const rpm = 75, eq = equilibrium(rpm);
  return { rpm, theta: eq.theta, thetaDot: 0, phi: 2.07, t: 0, turns: 0, message: '' };
}
export function setSpeed(state, value, snap) {
  const v = typeof value === 'number' ? value : Number(String(value).trim());
  if (String(value).trim() === '' || !Number.isFinite(v) || v < 0 || v > D.RPM_MAX)
    return { ...state, message: `Rejected: enter a speed from 0 to ${D.RPM_MAX} rpm` };
  const s = { ...state, rpm: v, message: `Speed set to ${v.toFixed(0)} rpm` };
  if (snap) { s.theta = equilibrium(v).theta; s.thetaDot = 0; }
  return s;
}
// Damped arm dynamics: L th'' = w^2 (E+L sin th) cos th - g sin th - c L th'
export function step(state, dt) {
  let { theta, thetaDot, phi } = state;
  const w = omegaOf(state.rpm), sub = Math.max(1, Math.ceil(dt / 0.004)), h = dt / sub;
  for (let i = 0; i < sub; i++) {
    const acc = (w * w * (D.E + D.L * Math.sin(theta)) * Math.cos(theta) - D.G * Math.sin(theta)) / D.L - D.DAMP * thetaDot;
    thetaDot += acc * h; theta += thetaDot * h;
    if (theta <= D.TH_MIN) { theta = D.TH_MIN; if (thetaDot < 0) thetaDot = 0; }
    if (theta >= D.TH_MAX) { theta = D.TH_MAX; if (thetaDot > 0) thetaDot = 0; }
  }
  phi += w * dt;
  const turns = state.turns + w * dt / (2 * Math.PI);
  return { ...state, theta, thetaDot, phi: phi % (2 * Math.PI), t: state.t + dt, turns };
}
export function readout(state) {
  const p = pose(state), eq = equilibrium(state.rpm);
  const stop = state.theta <= D.TH_MIN + 1e-6 ? 'resting on lower stop' : state.theta >= D.TH_MAX - 1e-6 ? 'against upper stop' : 'floating (balanced)';
  return { rpm: state.rpm, angle: state.theta * 180 / Math.PI, lift: p.lift, radius: p.ballRadius,
    eqAngle: eq.theta * 180 / Math.PI, stop, eqStop: eq.stop };
}

