import * as M from './model.mjs';
const D = M.DIM;
const dist = (a, b) => Math.hypot(a[0] - b[0], a[1] - b[1], a[2] - b[2]);
export function verify() {
  const out = [], add = (name, passed, detail = '') => out.push({ name, passed: !!passed, detail });
  // sample full stroke and full rotation
  let armErr = 0, linkErr = 0, ballErr = 0, pinErr = 0, mono = true, prevZ = -Infinity, clash = Infinity, sleeveIn = true;
  for (let i = 0; i <= 40; i++) {
    const th = D.TH_MIN + (D.TH_MAX - D.TH_MIN) * i / 40;
    for (let j = 0; j < 12; j++) {
      const p = M.pose({ theta: th, phi: j * Math.PI / 6 });
      for (const sd of p.sides) {
        armErr = Math.max(armErr, Math.abs(dist(sd.hinge, sd.joint) - D.A), Math.abs(dist(sd.hinge, sd.ball) - D.L));
        linkErr = Math.max(linkErr, Math.abs(dist(sd.joint, sd.pin) - D.B));
        pinErr = Math.max(pinErr, Math.abs(Math.hypot(sd.pin[0], sd.pin[1]) - D.C), Math.abs(sd.pin[2] - p.zs));
        // ball clear of sleeve and spindle: horizontal radius minus ball radius
        clash = Math.min(clash, Math.hypot(sd.ball[0], sd.ball[1]) - D.BALL_R - D.SLEEVE_R);
      }
      ballErr = Math.max(ballErr, Math.abs(p.sides[0].ball[2] - p.sides[1].ball[2]) + Math.abs(p.sides[0].ball[0] + p.sides[1].ball[0]));
      if (p.sleeve[0] < M.STOP_LOW_TOP - 1e-6 || p.sleeve[1] > M.STOP_HIGH_BOT + 1e-6) sleeveIn = false;
      if (j === 0) { if (p.zs < prevZ) mono = false; prevZ = p.zs; }
    }
  }
  add('Arm length fixed through stroke and rotation', armErr < 1e-6, `max err ${armErr.toExponential(2)} mm`);
  add('Link closure arm joint to sleeve pin', linkErr < 1e-6, `max err ${linkErr.toExponential(2)} mm`);
  add('Sleeve pins stay on the sleeve lug radius', pinErr < 1e-6);
  add('Balls symmetric about spindle', ballErr < 1e-6);
  add('Sleeve rises monotonically as arms open', mono);
  add('Sleeve stays between stop collars', sleeveIn);
  add('Balls clear the sleeve', clash > 5, `min clearance ${clash.toFixed(1)} mm`);
  const travel = M.SLEEVE_MAX - M.SLEEVE_MIN;
  add('Sleeve travel meaningful', travel > 60 && travel < 160, `${travel.toFixed(1)} mm`);
  add('Lower stop above upper bearing housing', M.STOP_LOW_TOP > D.HOUSING_Z1 + 2, `${M.STOP_LOW_TOP.toFixed(1)}`);
  add('Upper stop below hinge yoke', M.STOP_HIGH_BOT < D.Z_TOP - 30, `${M.STOP_HIGH_BOT.toFixed(1)}`);
  // equilibrium physics
  const lo = M.speedAt(D.TH_MIN), hi = M.speedAt(D.TH_MAX);
  add('Lift-off speed below upper-stop speed', lo < hi && lo > 20 && hi < D.RPM_MAX, `${lo.toFixed(1)}..${hi.toFixed(1)} rpm`);
  add('Low speed rests on lower stop', M.equilibrium(lo * 0.8).stop === 'lower' && M.equilibrium(0).theta === D.TH_MIN);
  add('High speed blocked by upper stop', M.equilibrium(Math.min(D.RPM_MAX, hi * 1.2)).stop === 'upper');
  let eqMono = true, pe = -1;
  for (let r = lo + 0.5; r < hi; r += 1) { const t = M.equilibrium(r).theta; if (t < pe) eqMono = false; pe = t; }
  add('Opening grows with speed', eqMono);
  // dynamics settles to equilibrium (state transition)
  let s = M.setSpeed(M.initial(), 85, false);
  for (let i = 0; i < 1500; i++) s = M.step(s, 1 / 60);
  const eq = M.equilibrium(85).theta;
  add('Damped dynamics settle to equilibrium', Math.abs(s.theta - eq) < 0.002, `${(s.theta * 57.3).toFixed(2)} vs ${(eq * 57.3).toFixed(2)} deg`);
  add('Rotation advances with speed', s.turns > 80 * 1500 / 60 / 60 * 0.99 && s.phi >= 0 && s.phi < 2 * Math.PI);
  let s0 = M.setSpeed(M.initial(), 0, false); for (let i = 0; i < 600; i++) s0 = M.step(s0, 1 / 60);
  add('Stopped spindle drops arms to lower stop', Math.abs(s0.theta - D.TH_MIN) < 1e-9);
  const bad = M.setSpeed(M.initial(), 'abc', true), neg = M.setSpeed(M.initial(), -5, true);
  add('Invalid speed rejected without changing state', bad.rpm === 75 && neg.rpm === 75 && bad.message.startsWith('Rejected'));
  return out;
}

