import * as M from './model.mjs';
import { makeView, draw } from './geometry.mjs';

export function mount(root, env) {
  let state = M.initial(), playing = false, raf = 0, last = 0, inspect = false, visible = true, view = null, vw = 0;
  const lo = M.speedAt(M.DIM.TH_MIN), hi = M.speedAt(M.DIM.TH_MAX);
  root.innerHTML = `<div class="gv">
  <div class="gv-controls">
    <label class="gv-range">Spindle speed <output id="speed-out">75 rpm</output>
      <input id="speed" type="range" min="0" max="${M.DIM.RPM_MAX}" step="1" value="75"></label>
    <div class="gv-row">
      <label>Exact rpm <input id="speed-input" type="text" inputmode="decimal" value="75" size="5"></label>
      <button id="set-speed" type="button">Set</button>
      <button id="play" type="button">Play</button>
      <button id="inspect" type="button" aria-pressed="false">Inspection view</button>
      <button id="reset" type="button">Reset</button>
    </div>
  </div>
  <div class="gv-stage"><div id="view-label" class="gv-viewlabel">Full assembly</div><svg id="art" role="img" aria-label="Isometric two-ball centrifugal governor"></svg></div>
  <div class="gv-read" aria-live="polite">
    <div><span>Arm angle</span><b id="readout-angle"></b></div>
    <div><span>Sleeve lift</span><b id="readout-lift"></b></div>
    <div><span>Ball radius</span><b id="readout-radius"></b></div>
    <div><span>Arm length</span><b id="readout-length">${M.DIM.L} mm (fixed)</b></div>
  </div>
  <p id="status" class="gv-status"></p>
  <p id="message" class="gv-msg"></p>
  <ol class="gv-legend"><li>Hinge yoke on spindle (arm pivot)</li><li>Arm–link clevis pin</li><li>Link pin on sliding sleeve</li><li>Lower stop collar</li></ol>
  <details class="gv-details"><summary>Model simplifications</summary><p>Arms and links are rigid and massless, balls are point masses at their centres, joints and the sleeve are frictionless, and the sleeve carries no throttle load. The arm obeys g·tanθ = ω²(e + L·sinθ) at balance, with a small numerical damping term during playback. Stops limit θ to ${(M.DIM.TH_MIN * 180 / Math.PI).toFixed(0)}–${(M.DIM.TH_MAX * 180 / Math.PI).toFixed(0)}°, so the arms float only between about ${lo.toFixed(0)} and ${hi.toFixed(0)} rpm. Not a load-rated engineering simulation.</p></details>
  </div>`;
  const $ = id => root.querySelector('#' + id);
  const svg = $('art');

  function frame() {
    const w = root.clientWidth || 640, narrow = w < 600;
    const W = narrow ? 360 : 640, H = narrow ? 440 : 500;
    if (!view || vw !== W || view.inspect !== inspect) { view = makeView(W, H, inspect); vw = W; svg.setAttribute('viewBox', `0 0 ${W} ${H}`); }
  }
  function render() {
    frame();
    svg.innerHTML = draw(view, state);
    const r = M.readout(state);
    $('speed-out').textContent = `${r.rpm.toFixed(0)} rpm`;
    $('readout-angle').textContent = `${r.angle.toFixed(1)}°`;
    $('readout-lift').textContent = `${r.lift.toFixed(1)} mm`;
    $('readout-radius').textContent = `${r.radius.toFixed(0)} mm`;
    $('status').textContent = `${playing ? 'Running' : 'Paused'} · arms ${r.stop} · ${state.turns.toFixed(1)} turns`;
    $('message').textContent = state.message;
    $('play').textContent = playing ? 'Pause' : 'Play';
    $('inspect').setAttribute('aria-pressed', String(inspect));
    $('inspect').textContent = inspect ? 'Full view' : 'Inspection view';
    $('view-label').textContent = inspect ? 'Inspection close-up: hinge, links, sleeve' : 'Full assembly';
  }
  function tick(ts) {
    raf = 0;
    if (!playing || !visible) return;
    const dt = Math.min(0.05, Math.max(0, (ts - last) / 1000)); last = ts;
    state = M.step(state, dt); render();
    raf = requestAnimationFrame(tick);
  }
  function start() { if (!raf && playing && visible) { last = performance.now(); raf = requestAnimationFrame(tick); } }
  function stop() { if (raf) cancelAnimationFrame(raf); raf = 0; }
  function apply(v) {
    state = M.setSpeed(state, v, !playing);
    $('speed').value = String(state.rpm); $('speed-input').value = String(state.rpm);
    render();
  }
  $('speed').addEventListener('input', e => apply(Number(e.target.value)));
  $('set-speed').addEventListener('click', () => apply($('speed-input').value));
  $('speed-input').addEventListener('keydown', e => { if (e.key === 'Enter') apply(e.target.value); });
  $('play').addEventListener('click', () => { playing = !playing; if (playing) start(); else stop(); render(); });
  $('inspect').addEventListener('click', () => { inspect = !inspect; render(); });
  $('reset').addEventListener('click', () => { stop(); playing = false; inspect = false; state = M.initial(); state.message = 'Reset to 75 rpm'; $('speed').value = '75'; $('speed-input').value = '75'; render(); });
  const onEnv = e => { const d = e.detail || {}; if (d.theme) env = { ...env, theme: d.theme }; if ('visible' in d) { visible = d.visible; if (visible) start(); else stop(); } };
  root.addEventListener('figure:environment', onEnv);
  const ro = new ResizeObserver(() => render()); ro.observe(root);
  render();
  return () => { stop(); ro.disconnect(); root.removeEventListener('figure:environment', onEnv); root.innerHTML = ''; };
}

