import * as k from '/kit/iso-kit.mjs';
import * as G from '/kit/lathe.mjs';
import { DIM as D, pose, STOP_LOW_TOP, STOP_HIGH_BOT } from './model.mjs';

const norm = v => { const l = Math.hypot(...v); return v.map(x => x / l); };
const add = (a, b, s = 1) => [a[0] + b[0] * s, a[1] + b[1] * s, a[2] + b[2] * s];

export function makeView(width, height, inspect) {
  const pts = [];
  if (inspect) {
    pts.push(...k.boxCorners({ x: -120, y: -120, w: 240, d: 240 }, STOP_LOW_TOP - 30, D.Z_TOP + 30));
  } else {
    const R = D.E + D.L * Math.sin(D.TH_MAX) + D.BALL_R;
    for (let i = 0; i < 24; i++) { const a = i * Math.PI / 12, x = R * Math.cos(a), y = R * Math.sin(a);
      pts.push([x, y, D.Z_TOP - D.L * Math.cos(D.TH_MIN) - D.BALL_R], [x, y, D.Z_TOP - D.L * Math.cos(D.TH_MAX) + D.BALL_R]); }
    pts.push([0, 0, D.SPINDLE_TOP]);
    pts.push(...k.boxCorners({ x: -150, y: -170, w: 300, d: 290 }, 0, 18));
  }
  const P = k.fitProjection(pts, width, height, { pad: 18, azimuth: 42, elevation: 26 });
  const z0 = k.depthOf([0, 0, 0], P), sg = k.depthOf([0, 0, 100], P) > z0 ? 1 : -1;
  // horizontal nearness key (z removed)
  const near = p => sg * (k.depthOf([p[0], p[1], 0], P) - z0);
  return { P, width, height, inspect, near, staticItems: buildStatic(P, near) };
}

function cyl(x, y, r, z0, z1, P, tone = 'mid', bevel = 1) {
  return k.solidSvg(k.cylinder(x, y, r, z0, z1 - z0, P, 32, bevel), { tone });
}

function buildStatic(P, near) {
  const it = [];
  const base = k.solidSvg(k.slabOf({ x: -150, y: -170, w: 300, d: 290, r: 14 }, 0, D.BASE_Z, P, 8, 3), { tone: 'lo' });
  it.push({ key: -1e9, z: 0, svg: base });
  for (const [x, y] of [[-125, -145], [125, -145], [-125, 95], [125, 95]])
    it.push({ key: -1e8 + near([x, y]), z: 1, svg: cyl(x, y, 9, D.BASE_Z, D.BASE_Z + 5, P, 'hi', 1) });
  const [px, py] = D.POST;
  it.push({ key: near([px, py]), z: D.BASE_Z, svg: cyl(px, py, D.POST_R + 7, D.BASE_Z, D.BASE_Z + 10, P, 'mid') + cyl(px, py, D.POST_R, D.BASE_Z + 10, D.HOUSING_Z1, P, 'mid') });
  it.push({ key: near([0, py / 2]), z: 136, svg: k.solidSvg(k.slabOf({ x: -12, y: py, w: 24, d: -py, r: 4 }, 136, 18, P, 6, 2), { tone: 'mid' }) });
  it.push({ key: 0, z: D.BASE_Z, svg: cyl(0, 0, 32, D.BASE_Z, D.BASE_Z + 8, P, 'lo') + cyl(0, 0, 24, D.BASE_Z + 8, D.FOOT_Z1, P, 'mid') });
  it.push({ key: 0, z: D.HOUSING_Z0, svg: cyl(0, 0, 27, D.HOUSING_Z0, D.HOUSING_Z1, P, 'mid', 2) + cyl(0, 0, 16, D.HOUSING_Z1, D.HOUSING_Z1 + 4, P, 'hi') });
  return it;
}

function rod(a, b, r, P, tone) {
  const d = [b[0] - a[0], b[1] - a[1], b[2] - a[2]], len = Math.hypot(...d);
  return k.solidSvg(G.lathe([[0, r], [len, r]], G.frameAlong(a, norm(d)), P), { tone });
}
function eye(c, axis, s0, s1, r, P, tone) {
  return k.solidSvg(G.disc(s0, s1, r, G.frameAlong(c, axis), P), { tone });
}

export function draw(view, state) {
  const { P, near } = view, p = pose(state), it = [...view.staticItems];
  const ax = (z0, z1, r, tone, b = 1) => it.push({ key: 0, z: z0, svg: cyl(0, 0, r, z0, z1, P, tone, b) });
  ax(D.FOOT_Z1, p.sleeve[0], D.SPINDLE_R, 'hi', 0);
  ax(D.PULLEY_Z0, D.PULLEY_Z0 + 8, D.PULLEY_R, 'mid');
  ax(D.PULLEY_Z0 + 8, D.PULLEY_Z1 - 8, D.PULLEY_R - 7, 'lo', 0);
  ax(D.PULLEY_Z1 - 8, D.PULLEY_Z1, D.PULLEY_R, 'mid');
  ax(STOP_LOW_TOP - 10, STOP_LOW_TOP, 16, 'lo');
  ax(p.sleeve[1], D.Z_TOP - 16, D.SPINDLE_R, 'hi', 0);
  ax(STOP_HIGH_BOT, STOP_HIGH_BOT + 10, 16, 'lo');
  // sleeve: flange, groove, body
  ax(p.sleeve[0], p.sleeve[0] + 10, D.SLEEVE_R + 4, 'mid');
  ax(p.sleeve[0] + 10, p.sleeve[0] + 20, D.SLEEVE_R - 4, 'lo', 0);
  ax(p.sleeve[0] + 20, p.sleeve[1], D.SLEEVE_R, 'hi');
  ax(D.Z_TOP - 16, D.Z_TOP + 14, 17, 'mid', 2);
  ax(D.Z_TOP + 14, D.SPINDLE_TOP, 10, 'hi');
  // rotation marker on pulley flange
  const m = [Math.cos(state.phi) * (D.PULLEY_R - 6), Math.sin(state.phi) * (D.PULLEY_R - 6), D.PULLEY_Z1];
  it.push({ key: near(m) * 0.01, z: D.PULLEY_Z1 + 1, svg: k.solidSvg(k.cylinder(m[0], m[1], 4, m[2], 2, P, 12, 0), { tone: 'hi' }) });
  const n = p.n;
  for (const sd of p.sides) {
    const kk = near(sd.dir) * 0.001;
    const push = (pt, svg, o = 0) => it.push({ key: near(pt) + kk + o, z: pt[2], svg });
    push(sd.hinge, eye(add(sd.hinge, n, -11), n, 0, 5, 10, P, 'mid') + eye(add(sd.hinge, n, 6), n, 0, 5, 10, P, 'mid'));
    const tip = add(sd.hinge, norm([sd.ball[0] - sd.hinge[0], sd.ball[1] - sd.hinge[1], sd.ball[2] - sd.hinge[2]]), D.L - D.BALL_R + 3);
    const mid = add(sd.hinge, sd.joint, 1).map(v => v / 2);
    push(mid, rod(sd.hinge, tip, 5, P, 'mid') + eye(sd.hinge, n, -5, 5, 8, P, 'hi') + eye(sd.joint, n, -5, 5, 8, P, 'hi') + eye(sd.hinge, n, -13, 13, 3.5, P, 'lo'));
    push(sd.ball, `<g class="gv-accent">${k.solidSvg(G.sphereOf(sd.ball, D.BALL_R, P), { tone: 'hi' })}</g>`, 1);
    push(sd.pin, eye(sd.pin, n, -4, 4, 9, P, 'mid'), 0.5);
    for (const o of [-8, 8]) {
      const a = add(sd.joint, n, o), b = add(sd.pin, n, o);
      const lm = add(a, b, 1).map(v => v / 2);
      push(lm, rod(a, b, 3.2, P, 'lo') + eye(a, n, -2.5, 2.5, 7, P, 'mid') + eye(b, n, -2.5, 2.5, 7, P, 'mid'), o > 0 ? 0.6 : 0.4);
    }
    push(sd.joint, eye(sd.joint, n, -11, 11, 3.2, P, 'lo'), 0.8);
    push(sd.pin, eye(sd.pin, n, -11, 11, 3.2, P, 'lo'), 0.8);
  }
  const sweep = k.lineSvg(k.ring(0, 0, p.ballRadius, p.sides[0].ball[2], P), { tone: 'faint' });
  it.push({ key: -9e8, z: 0, svg: `<g class="gv-sweep">${sweep}</g>` });
  it.sort((a, b) => a.key - b.key || a.z - b.z);
  const front = p.sides.reduce((a, b) => (near(b.dir) > near(a.dir) ? b : a));
  const marks = [[front.hinge, '1'], [front.joint, '2'], [front.pin, '3'], [[0, 0, STOP_LOW_TOP - 5], '4']].map(([w, t]) => {
    const [x, y] = k.iso(w, P);
    return `<g class="gv-mark"><circle cx="${(x + 16).toFixed(1)}" cy="${(y - 14).toFixed(1)}" r="7"/><text x="${(x + 16).toFixed(1)}" y="${(y - 11).toFixed(1)}" text-anchor="middle">${t}</text></g>`;
  }).join('');
  const defs = '<defs><radialGradient id="gv-ball" cx="0.36" cy="0.32" r="0.75"><stop offset="0" stop-color="#f3b08a"/><stop offset="0.45" stop-color="#c8582c"/><stop offset="1" stop-color="#6e2a12"/></radialGradient></defs>';
  return defs + it.map(i => i.svg).join('') + marks;
}
